<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Crypto;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\Release;use App\Services\UpdateService;final class UpdateController extends AdminController{public function index(Request $I):Response{return $this->view('admin/updates/index',['releases'=>Release::all('published_at','DESC'),'public_key'=>Crypto::publicKeyB64(),'editor_token'=>(string)setting('updates.editor_token'),'meta'=>['title'=>t('admin.updates')]]);}public function create(Request $G):Response{return $this->view('admin/updates/create',['meta'=>['title'=>t('admin.publish_release')]]);}public function store(Request $E):Response{if($u=$this->validate($E,['version'=>'required|semver','channel'=>'required|in:stable,beta','min_version'=>'required|semver'],'/admin/updates/create')){return $u;}$e=$E->files['package']??null;$W=['version'=>$E->str('version'),'channel'=>$E->str('channel'),'min_version'=>$E->str('min_version'),'notes_url'=>$E->str('notes_url')?:null,'changelog'=>$this->multilang($E->input('changelog'))];try{if($e&&($e['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK){$m=(string)$e['name'];if(!preg_match('/\.(tar\.gz|tgz)$/i',$m)||(int)$e['size']>512*1024*1024){throw new \InvalidArgumentException(t('admin.invalid_package'));}$c=(string)file_get_contents($e['tmp_name'],false,null,0,2);if($c!=="\x1f\x8b"){throw new \InvalidArgumentException(t('admin.invalid_package'));}$i=UpdateService::publishFromFile($e['tmp_name'],$W,$m);}else{$W['download_url']=$E->str('download_url');$W['sha256']=strtolower($E->str('sha256'));$W['size']=$E->int('size');$i=UpdateService::publishManifest($W);}}catch(\Throwable $w){$this->flash('error',$w->getMessage());return $this->redirect('/admin/updates/create');}$this->flash('success',t('admin.release_published').' '.$i['version']);return $this->redirect('/admin/updates');}public function toggle(Request $m,string $r):Response{$g=Release::find((int)$r);if($g){Release::update((int)$r,['is_active'=>(int)$g['is_active']?0:1]);AuditLog::log('admin.release_toggle',$g['version']);}return $this->redirect('/admin/updates');}public function delete(Request $X,string $n):Response{$A=Release::find((int)$n);if($A){if($A['file_path']&&is_file(TP_ROOT.'/'.$A['file_path'])){@unlink(TP_ROOT.'/'.$A['file_path']);}Release::delete((int)$n);AuditLog::log('admin.release_delete',$A['version']);}$this->flash('success',t('common.deleted'));return $this->redirect('/admin/updates');}}